    }

    /**
     * Get Observability Funnel.
     *
     * Per-node funnel for Observability v2.
     *
     * Returns items in canvas order with count (distinct runs that successfully executed the node) and
     * drop_from_previous (fraction lost between consecutive nodes). The first row is always the
     * trigger.
     *
     * Window defaults to the last 30 days.
     *
     * Scopes: flows:read.
     *
     * @param  ?string  $since  ISO8601 UTC start
     * @param  ?string  $until  ISO8601 UTC end
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/get_observability_funnel_api_v1_flows__flow_id__observability_funnel_get
     */
    public function getObservabilityFunnel(string $flowId, ?string $since = null, ?string $until = null): Funnel
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/observability/funnel',
            query: Payload::query(['since' => $since, 'until' => $until]),
        ));

        return Funnel::fromArray($response->data());
    }

    /**
     * Pause Flow.
     *
     * Pause a published flow.
     *
     * New POST /flows/{id}/runs calls return 409 while paused (FlowEngineService.start_run requires
     * PUBLISHED). In-flight runs continue — operators want to drain.
     *
     * Idempotent on already-paused.
     *
     * Scopes: flows:write.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/pause_flow_api_v1_flows__flow_id__pause_post
     */
    public function pause(string $flowId, ?string $idempotencyKey = null): AppSchemasFlowSchemaFlow
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/flows/'.Payload::segment($flowId).'/pause',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return AppSchemasFlowSchemaFlow::fromArray($response->data());
    }

    /**
     * Delete Flow Permanently.
     *
     * Permanently delete a flow — irreversible, destroys run history.
     *
     * Distinct from DELETE /flows/{id}, which soft-archives (reversible via POST
     * /flows/{id}/unarchive). This endpoint removes the flows row AND every child row: flow_runs,
     * flow_run_steps, flow_run_waits. No FK cascades exist on the flow tables, so the service deletes
     * children explicitly inside one transaction. Keyword-bot wiring that pointed at the flow is
     * detached (set to NULL) rather than deleted. Conversation messages and tracked_links produced by
     * the flow are KEPT — they are real history and their flow attribution readers are already
     * best-effort.
     *
     * Refuses with 409 rather than corrupting state:
     *
     * Scopes: flows:write.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/delete_flow_permanently_api_v1_flows__flow_id__permanent_delete
     */
    public function deletePermanently(string $flowId): void
    {
        $this->connector->send(new Request(
            Method::Delete,
            '/flows/'.Payload::segment($flowId).'/permanent',
        ));
    }

    /**
     * Publish Flow.
     *
     * Publish a flow.
     *
     * Runs the stricter publish-time validation pass:
     *
     * - Every node reachable from entry_node_id. - No orphan nodes. - Every condition has both
     * yes_node_id + no_node_id wired. - No infinite cycles in synchronous-only paths
     * (Delay/Send-bearing cycles are allowed — they're the legitimate "drip every day" pattern).
     *
     * Scopes: flows:publish.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/publish_flow_api_v1_flows__flow_id__publish_post
     */
    public function publish(string $flowId, ?string $idempotencyKey = null): AppSchemasFlowSchemaFlow
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/flows/'.Payload::segment($flowId).'/publish',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return AppSchemasFlowSchemaFlow::fromArray($response->data());
    }

    /**
     * List Flow Runs.
     *
     * List runs for a flow.
     *
     * Scopes: flows:read.
     *
     * @param  ?string  $contactId  Filter to runs for this contact
     * @param  FlowRunStatus|string|null  $status  Filter by run status (running, waiting, completed, failed, canceled).
     * @return Page<FlowRun>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/list_flow_runs_api_v1_flows__flow_id__runs_get
     */
    public function listRuns(string $flowId, ?string $contactId = null, FlowRunStatus|string|null $status = null, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/runs',
            query: Payload::query(['contact_id' => $contactId, 'status' => $status, 'page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), FlowRun::fromArray(...), fn (int $page): Page => $this->listRuns(flowId: $flowId, contactId: $contactId, status: $status, page: $page, pageSize: $pageSize));
    }

    /**
     * Start Flow Run.
     *
     * Start a flow run for a contact.
     *
     * Honors idempotency from EITHER the request body field idempotency_key OR the HTTP header
     * Idempotency-Key (body wins on conflict). The engine's start_run returns the existing run on
     * collision with HTTP 200; new runs return HTTP 201.
     *
     * Returns 409 if the flow isn't published, 404 if the contact doesn't exist on this tenant, 409
     * FLOW_RUN_BLOCKED when the re-entry policy is block and an active run already exists.
     *
     * Scopes: flows:write.
     *
     * @param  string  $contactId  Contact UUID on the tenant's shard
     * @param  array<string, mixed>|null  $contactMethodOverrides  Optional map of ``ChannelType`` (string value, e.g. ``email``, ``sms``, ``whatsapp``, ``telegram``, ``messenger``, ``instagram``, ``browser_push``) → ``contact_method.id``. When the flow sends on the matching channel, this specific contact_method's value is used as the destination instead of the contact's primary method. Per-channel keys are independent; omitted channels fall back to the default (primary) resolution. Each referenced contact_method must belong to the same tenant, the same contact, and have a method_type that matches the channel key.
     * @param  array<string, mixed>|null  $context  Extra variables to seed ``flow_runs.context.vars``. Hard-capped at 16 KB JSON-encoded.
     * @param  ?string  $idempotencyKey  Optional caller-supplied idempotency key for at-most-once start semantics. If a run with the same (tenant_id, idempotency_key) already exists, the existing run is returned with HTTP 200 instead of creating a new one. If omitted, the engine derives a key from the request payload (e.g. ``manual:<flow_id>:<contact_id>:<request_id>``).
     * @param  ?string  $idempotencyKeyIdempotency  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/start_flow_run_api_v1_flows__flow_id__runs_post
     */
    public function startRun(string $flowId, string $contactId, ?array $contactMethodOverrides = null, ?array $context = null, ?string $idempotencyKey = null, ?string $idempotencyKeyIdempotency = null): FlowRun
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/flows/'.Payload::segment($flowId).'/runs',
            body: Payload::body(['contact_id' => $contactId, 'contact_method_overrides' => $contactMethodOverrides, 'context' => $context, 'idempotency_key' => $idempotencyKey]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return FlowRun::fromArray($response->data());
    }

    /**
     * Get Flow Run.
     *
     * Fetch a single flow run.
     *
     * Scopes: flows:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/get_flow_run_api_v1_flows__flow_id__runs__run_id__get
     */
    public function getRun(string $flowId, string $runId): FlowRun
