    }

    /**
     * List Flow Run Messages.
     *
     * List every message attributed to a single flow run, oldest-first.
     *
     * Returns the chronological transcript of outbound (Send-node) and inbound (Wait-for-reply
     * matched) messages stamped with this flow_run_id. Reuses the existing idx_msg_flow_run_id /
     * idx_messages_tenant_flow_run index.
     *
     * 404 when the run does not exist on this tenant OR when the run exists but does not belong to
     * flow_id — never leak cross-tenant runs.
     *
     * Scopes: flows:read, conversations:read.
     *
     * @return Page<FlowRunMessage>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/list_flow_run_messages_api_v1_flows__flow_id__runs__run_id__messages_get
     */
    public function listRunMessages(string $flowId, string $runId, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/runs/'.Payload::segment($runId).'/messages',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), FlowRunMessage::fromArray(...), fn (int $page): Page => $this->listRunMessages(flowId: $flowId, runId: $runId, page: $page, pageSize: $pageSize));
    }

    /**
     * Get Run Replay.
