     * Merges flow_run_steps (engine audit trail) with messages (outbound + inbound tagged with this
     * flow_run_id) into a single time-ordered event stream. Returns the contact header + the run
     * summary + the full event list.
     *
     * Scopes: flows:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/get_run_replay_api_v1_flows__flow_id__runs__run_id__replay_get
     */
    public function getRunReplay(string $flowId, string $runId): Replay
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/runs/'.Payload::segment($runId).'/replay',
        ));

        return Replay::fromArray($response->data());
    }

    /**
     * List Flow Run Steps.
     *
     * List the audit-trail rows for a single flow run, oldest first.
     *
     * Each row is enriched from the CURRENT flows.definition: * node_label — editor-visible label
     * (display_name → snapshot label/name → derived). * node_config_snapshot — a curated subset
     * of the node's current config (e.g. for collect_input: validation, max_attempts,
     * on_timeout_node_id, prompt). NOT a point-in-time snapshot of what the engine executed —
     * callers that need that fidelity should rely on input_snapshot. * branch_taken — best-effort
     * from output_snapshot.chosen_branch.
     *
     * Scopes: flows:read.
     *
     * @return Page<FlowRunStep>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/list_flow_run_steps_api_v1_flows__flow_id__runs__run_id__steps_get
     */
    public function listRunSteps(string $flowId, string $runId, ?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/runs/'.Payload::segment($runId).'/steps',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), FlowRunStep::fromArray(...), fn (int $page): Page => $this->listRunSteps(flowId: $flowId, runId: $runId, page: $page, pageSize: $pageSize));
    }

