    public function stopRun(string $flowId, string $runId, ?string $idempotencyKey = null): FlowRun
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/flows/'.Payload::segment($flowId).'/runs/'.Payload::segment($runId).'/stop',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return FlowRun::fromArray($response->data());
    }

