    /**
     * Get Flow Validation.
     *
     * Return the publish-time validation snapshot for a flow.
     *
     * Same shape as FlowResponse.validation — exposed as a dedicated endpoint so the Flows editor
     * can poll cheap validation passes after local edits without re-fetching the whole flow row. The
     * Flows editor uses this to gate the "Activate" button and surface inline {path, message} warnings
     * on the offending nodes / trigger.
     *
     * Scopes: flows:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Flows/get_flow_validation_api_v1_flows__flow_id__validation_get
     */
    public function getValidation(string $flowId): FlowValidationStatus
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/flows/'.Payload::segment($flowId).'/validation',
        ));

        return FlowValidationStatus::fromArray($response->data());
    }
